const input = $('Execute Workflow Trigger').first().json;
const rows = $input.all().map(i=>i.json);
const u = rows[0];
if(!u) return [{json:{ok:false, motivo:'Usuario no encontrado'}}];
if(!u.autorizado) return [{json:{ok:false, motivo:'Usuario no autorizado'}}];
if(!u.activo) return [{json:{ok:false, motivo:'Usuario inactivo'}}];
const rolRequerido = input.rolRequerido;
if(rolRequerido && u.rol !== rolRequerido) return [{json:{ok:false, motivo:'Rol no permitido'}}];
return [{json:{ok:true, usuario:u}}];
